def coerce_cli_value(value)
  inspect_cli_tokens(value)
  return true if value == 'true' || value == 'yes'
  return false if value == 'false' || value == 'no'
  return value
end


def binary_safe_text(value)
  text = value.to_s
  return text if text.valid_encoding?
  text.dup.force_encoding(Encoding::ASCII_8BIT)
end

def remember_shared_presentation(key, value)
  @presentation_plan ||= {}
  @presentation_plan[key] = value
  @presentation_plan
end

